class Solution {
    public int trailingZeroes(int n) {
        int count = 0;
        while (n >= 5) {
            n /= 5;
            count += n;
        }
        return count;
    }
}

class Solution {
    public int trailingZeroes(int n) {
        int count = 0;
        for (long factor = 5; factor <= n; factor *= 5) {
            count += n / factor;
        }
        return count;
    }
}

class Solution {
    public int trailingZeroes(int n) {
        if (n < 5) {
            return 0;
        }
        return n / 5 + trailingZeroes(n / 5);
    }
}

class Solution {
    public int trailingZeroes(int n) {
        int count = 0;
        for (int value = 5; value <= n; value += 5) {
            int current = value;
            while (current % 5 == 0) {
                count++;
                current /= 5;
            }
        }
        return count;
    }
}

class Solution {
    public int trailingZeroes(int n) {
        int twos = 0;
        int fives = 0;
        for (int value = 1; value <= n; value++) {
            int current = value;
            while (current % 2 == 0) {
                twos++;
                current /= 2;
            }
            current = value;
            while (current % 5 == 0) {
                fives++;
                current /= 5;
            }
        }
        return Math.min(twos, fives);
    }
}
